package com.justjava.humanresource.employeeexit.service;
import com.justjava.humanresource.employeeexit.dto.SettlementLineCommand; import com.justjava.humanresource.employeeexit.entity.*; import com.justjava.humanresource.employeeexit.enums.ExitPackageCalculationMethod; import com.justjava.humanresource.employeeexit.repository.*; import com.justjava.humanresource.hr.repository.EmployeeRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.math.*; import java.util.*;
@Service @RequiredArgsConstructor public class ExitPackageCalculationService {
 private final ExitPackageRuleRepository rules; private final ExitPackageComponentRepository components; private final EmployeeRepository employees;
 public List<SettlementLineCommand> calculate(EmployeeExitCase x,BigDecimal monthlyBasic,BigDecimal leaveDays){var employee=employees.findById(x.getEmployeeId()).orElseThrow();int years=employee.getDateOfHire()==null?0:Math.max(0,java.time.Period.between(employee.getDateOfHire(),x.getEffectiveExitDate()==null?x.getProposedLastWorkingDate():x.getEffectiveExitDate()).getYears());List<SettlementLineCommand> result=new ArrayList<>();for(ExitPackageRule r:rules.findByActiveTrue()){if(!applies(r,x,years)||r.getCalculationMethod()==ExitPackageCalculationMethod.MANUAL)continue;ExitPackageComponent c=components.findById(r.getComponentId()).orElseThrow();if(!c.isActive())continue;BigDecimal amount=switch(r.getCalculationMethod()){case FIXED_AMOUNT->nz(r.getFixedAmount());case PERCENT_OF_BASIC->nz(monthlyBasic).multiply(nz(r.getPercentage())).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP);case YEARS_OF_SERVICE_MULTIPLIER->nz(monthlyBasic).multiply(BigDecimal.valueOf(years));case MONTHS_OF_SERVICE->nz(monthlyBasic).multiply(BigDecimal.valueOf(years*12L));case LEAVE_BALANCE->nz(monthlyBasic).divide(BigDecimal.valueOf(30),2,RoundingMode.HALF_UP).multiply(nz(leaveDays));case DAYS_PRORATED->nz(monthlyBasic).divide(BigDecimal.valueOf(30),2,RoundingMode.HALF_UP);default->BigDecimal.ZERO;};SettlementLineCommand line=new SettlementLineCommand();line.setLineType(c.getLineType());line.setComponentCode(c.getComponentCode());line.setDescription(c.getName());line.setAmount(amount.setScale(2,RoundingMode.HALF_UP));line.setEarning(c.isEarning());line.setTaxable(c.isTaxable());line.setSource("EXIT_PACKAGE_RULE_"+r.getId());result.add(line);}return result;}
 private boolean applies(ExitPackageRule r,EmployeeExitCase x,int years){if(r.getAppliesToExitTypes()!=null&&!Arrays.asList(r.getAppliesToExitTypes().split(",")).contains(x.getExitType().name()))return false;return(r.getMinimumYearsOfService()==null||years>=r.getMinimumYearsOfService())&&(r.getMaximumYearsOfService()==null||years<=r.getMaximumYearsOfService());}private BigDecimal nz(BigDecimal v){return v==null?BigDecimal.ZERO:v;}
}
